from typing import List


class Solution:
    def minOperations(self, nums: List[int], k: int) -> int:
        if min(nums) < k:
            return -1
        ops = 0
        for v in range(max(nums), k + 1, -1):
            if v in nums:
                ops += 1
        return ops

